"""Shared result shapes of vecDSL searches. Generated by vecDSL 7. Do not edit.

One implementation of the result-shape clauses (boost, cursor, mmr, group-by with size, sort, offset and limit, score
bounds, with-total, aggregate, exclude, with-vectors) over the candidate window a target retrieved, following the pgvector
generator's pipeline. The same module exists in TypeScript and
Java; equal input gives equal output in the three languages (generator/common/shapes/README.md). Standard library only.

A candidate is {key, score, fields, vectors?, highlight?, explanation?}: score is the canonical similarity (higher is
better), the native score under `score native`, or None for a scroll, whose records have no score.
"""

from __future__ import annotations

import json
import math
import re
import time
from decimal import Decimal
from functools import cmp_to_key
from typing import Any, Sequence

_DIGITS = 6
_PERCENTS = (1, 5, 25, 50, 75, 95, 99)
_UNITS = {"ms": 0.001, "msec": 0.001, "msecs": 0.001, "millisecond": 0.001, "milliseconds": 0.001,
          "s": 1.0, "sec": 1.0, "secs": 1.0, "second": 1.0, "seconds": 1.0,
          "m": 60.0, "min": 60.0, "mins": 60.0, "minute": 60.0, "minutes": 60.0,
          "h": 3600.0, "hr": 3600.0, "hrs": 3600.0, "hour": 3600.0, "hours": 3600.0,
          "d": 86400.0, "day": 86400.0, "days": 86400.0,
          "w": 604800.0, "week": 604800.0, "weeks": 604800.0}
_INTERVAL = re.compile(r"\s*([0-9]+(?:\.[0-9]+)?)\s*([A-Za-z]+)")
_NUMBER = re.compile(r"[+-]?(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?")
_TIMESTAMP = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})(?:[T ]([0-9]{2}):([0-9]{2})(?::([0-9]{2})(\.[0-9]+)?)?)?"
                        r"(Z|z|[+-][0-9]{2}(?::?[0-9]{2})?)?")


class UnsupportedShape(NotImplementedError):
    """A combination of result-shape clauses the module refuses, with pgvector's reason."""


class _Hit:
    __slots__ = ("key", "score", "fields", "vectors", "highlight", "explanation", "ord")

    def __init__(self, key: Any, score: Any, fields: dict[str, Any], vectors: dict[str, Any], highlight: Any, explanation: Any) -> None:
        self.key = key
        self.score = score
        self.fields = fields
        self.vectors = vectors
        self.highlight = highlight
        self.explanation = explanation
        self.ord = 0


def window_size(spec: dict[str, Any]) -> int | None:
    """Candidates a target retrieves for the spec: the mmr pool when its `candidates` is written, else ten times limit plus
    offset when a shape clause is written, else limit plus offset; None (every matching record) for a scroll that sorts or
    resumes after a cursor, or has no limit."""
    limit = spec.get("limit")
    offset = int(spec.get("offset") or 0)
    if limit is None:
        return None
    if spec.get("score", "similarity") is None:
        return None if spec.get("sort") or spec.get("cursor") is not None else int(limit) + offset
    fetch = int(limit) + offset
    mmr = spec.get("mmr")
    if mmr is not None and mmr.get("candidates") is not None:
        return max(int(mmr["candidates"]), fetch)
    return 10 * fetch if _shaped(spec) else fetch


def _shaped(spec: dict[str, Any]) -> bool:
    return (spec.get("cursor") is not None or spec.get("boost") is not None or spec.get("mmr") is not None
            or spec.get("group") is not None or bool(spec.get("sort")) or bool(spec.get("withTotal"))
            or bool(spec.get("aggregations")))


def shape(candidates: Sequence[dict[str, Any]], spec: dict[str, Any]) -> Any:
    """The result of a search from its candidate window: a list of hits, a list of {group, hits}, or {hits, total,
    aggregations} when with-total or aggregate is written."""
    _refuse(spec)
    form = spec.get("score", "similarity")
    key_field = spec.get("keyField") or "id"
    offset = int(spec.get("offset") or 0)
    limit = None if spec.get("limit") is None else int(spec["limit"])
    bounds = spec.get("bounds") or {}
    clauses = spec.get("sort") or []
    hits = _hits(candidates, form is None)
    if form is None:
        ranked = sorted(hits, key=cmp_to_key(lambda a, b: _by_clauses(a, b, clauses) or _compare_keys(a.key, b.key)))
    elif form == "native":
        ranked = hits
    else:
        ranked = sorted(hits, key=cmp_to_key(_by_relevance))
    if spec.get("boost") is not None:
        _boost(ranked, spec["boost"])
        ranked.sort(key=cmp_to_key(_by_relevance))
    for position, hit in enumerate(ranked):
        hit.ord = position
    matched = ranked
    if spec.get("cursor") is not None:
        ranked = _after(ranked, spec["cursor"])
    result: Any
    if spec.get("group") is not None:
        result = _groups(ranked, spec, bounds, key_field, offset, limit)
    else:
        if spec.get("mmr") is not None:
            page = _diverse(ranked, spec["mmr"], offset, limit)
        else:
            page = ranked[offset:] if limit is None else ranked[offset:offset + limit]
        if form is not None and clauses:
            page = [hit for _, hit in sorted(enumerate(page), key=cmp_to_key(
                lambda a, b: _by_clauses(a[1], b[1], clauses) or a[0] - b[0]))]
        result = [_project(hit, spec, key_field) for hit in page if _within(hit.score, bounds)]
    if spec.get("withTotal") or spec.get("aggregations"):
        inside = [hit for hit in matched if _within(hit.score, bounds)]
        wrapped: dict[str, Any] = {"hits": result}
        if spec.get("withTotal"):
            wrapped["total"] = len(inside)
        if spec.get("aggregations"):
            wrapped["aggregations"] = {_name(a): _aggregate(inside, a) for a in spec["aggregations"]}
        result = wrapped
    return _value(result)


def _refuse(spec: dict[str, Any]) -> None:
    form = spec.get("score", "similarity")
    group, mmr, boost = spec.get("group") is not None, spec.get("mmr") is not None, spec.get("boost") is not None
    if spec.get("cursor") is not None and (group or mmr):
        raise UnsupportedShape("the 'cursor' clause with group-by or mmr; keyset pagination continues after one record in an "
                               "order that each record's own values decide")
    if group and spec.get("sort"):
        raise UnsupportedShape("sort with group-by; groups follow the relevance of their best hit")
    if group and mmr:
        raise UnsupportedShape("mmr with group-by; MMR selects single hits, groups select records per group value")
    if boost and form == "native":
        raise UnsupportedShape("boosts with score native; boosts apply to the canonical similarity, where higher is better")
    if mmr and form == "native":
        raise UnsupportedShape("mmr with score native; MMR weighs the canonical similarity, which a native score does not give")
    if form is None and (boost or mmr or group):
        raise UnsupportedShape("boost, mmr and group-by on a scroll, whose records have no score")
    if mmr and not 0 <= float(spec["mmr"]["lambda"]) <= 1:
        raise UnsupportedShape("an mmr lambda outside 0 to 1")
    for function in (spec["boost"].get("functions") or []) if boost else []:
        rate = function.get("rate")
        if function.get("kind") == "decay" and rate is not None and not 0 < float(rate) < 1:
            raise UnsupportedShape("a decay rate outside the open interval from 0 to 1")
    for a in spec.get("aggregations") or []:
        if a.get("kind") == "range":
            raise UnsupportedShape("range aggregations; vecDSL gives no range bounds to count records in")


def _hits(candidates: Sequence[dict[str, Any]], unscored: bool) -> list[_Hit]:
    hits = []
    seen = set()
    for candidate in candidates:
        if not isinstance(candidate, dict):
            raise ValueError("a candidate is not an object")
        key = candidate.get("key")
        if not (isinstance(key, str) or _number(key) and math.isfinite(key)):
            raise ValueError(f"a candidate key must be a string or a finite number: {_canonical(key)}")
        identity = _canonical(key)
        if identity in seen:
            raise ValueError(f"duplicate candidate key {identity}")
        seen.add(identity)
        score = candidate.get("score")
        if score is not None and not (_number(score) and math.isfinite(score)):
            raise ValueError(f"the score of candidate {identity} is not a finite number")
        if score is None and not unscored:
            raise ValueError(f"candidate {identity} has no score")
        fields = candidate.get("fields")
        vectors = candidate.get("vectors")
        fields = {} if fields is None else fields
        vectors = {} if vectors is None else vectors
        if not isinstance(fields, dict) or not isinstance(vectors, dict):
            raise ValueError(f"the fields or vectors of candidate {identity} are not an object")
        hits.append(_Hit(key, score, fields, vectors, candidate.get("highlight"), candidate.get("explanation")))
    return hits


def _number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


# ---------------------------------------------------------------- order


def _compare_keys(a: Any, b: Any) -> int:
    """Keys: numbers before strings, numbers by value, strings by code point (the runtimes' _order)."""
    if _number(a) != _number(b):
        return -1 if _number(a) else 1
    return (a > b) - (a < b)


def _by_relevance(a: _Hit, b: _Hit) -> int:
    return (b.score > a.score) - (b.score < a.score) or _compare_keys(a.key, b.key)


def _rank(value: Any) -> int:
    if _number(value):
        return 0
    if isinstance(value, str):
        return 1
    if isinstance(value, bool):
        return 2
    return 3


def _compare_values(a: Any, b: Any) -> int:
    """Field values: numbers, then strings by code point, then booleans, then lists and objects by their JSON text."""
    ra, rb = _rank(a), _rank(b)
    if ra != rb:
        return ra - rb
    if ra == 3:
        a, b = _canonical(a), _canonical(b)
    return (a > b) - (a < b)


def _by_clauses(a: _Hit, b: _Hit, clauses: Sequence[dict[str, Any]]) -> int:
    """Sort keys: field values with missing values last in both directions, relevance by rank."""
    for clause in clauses:
        descending = clause.get("direction") == "desc"
        if clause.get("relevance"):
            result = a.ord - b.ord if descending else b.ord - a.ord
        else:
            va, vb = _path(a.fields, clause["field"]), _path(b.fields, clause["field"])
            if va is None or vb is None:
                result = (va is None) - (vb is None)
            else:
                result = -_compare_values(va, vb) if descending else _compare_values(va, vb)
        if result:
            return result
    return 0


def _path(fields: Any, path: Sequence[str]) -> Any:
    value = fields
    for segment in path:
        value = value.get(segment) if isinstance(value, dict) else None
    return value


def _canonical(value: Any) -> str:
    """JSON text with numbers as JavaScript prints them and object keys in code point order: the identity of a key, a group
    value or a term, and the text of values in messages, equal in the three languages."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if _number(value):
        return _number_text(value)
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, list):
        return "[" + ",".join(_canonical(item) for item in value) + "]"
    if isinstance(value, dict):
        return "{" + ",".join(json.dumps(str(k), ensure_ascii=False) + ":" + _canonical(value[k]) for k in sorted(value, key=str)) + "}"
    return json.dumps(str(value), ensure_ascii=False)


def _number_text(value: Any) -> str:
    """A number as JavaScript's Number::toString writes it (shortest round-trip digits)."""
    if isinstance(value, int) and abs(value) < 2 ** 53:
        return str(value)
    value = float(value)
    if math.isnan(value):
        return "NaN"
    if math.isinf(value):
        return "Infinity" if value > 0 else "-Infinity"
    if value == 0:
        return "0"
    _, digits, exponent = Decimal(repr(abs(value))).normalize().as_tuple()
    text = "".join(str(d) for d in digits)
    k = len(text)
    n = k + int(exponent)
    sign = "-" if value < 0 else ""
    if k <= n <= 21:
        return sign + text + "0" * (n - k)
    if 0 < n <= 21:
        return sign + text[:n] + "." + text[n:]
    if -6 < n <= 0:
        return sign + "0." + "0" * -n + text
    e = n - 1
    mantissa = text if k == 1 else text[0] + "." + text[1:]
    return sign + mantissa + "e" + ("+" if e >= 0 else "-") + str(abs(e))


# ---------------------------------------------------------------- cursor, groups, mmr, bounds


def _after(ranked: list[_Hit], cursor: Any) -> list[_Hit]:
    """The hits after the cursor record in the result order; none when no candidate has the cursor key."""
    for position, hit in enumerate(ranked):
        if _same_key(hit.key, cursor):
            return ranked[position + 1:]
    return []


def _same_key(key: Any, cursor: Any) -> bool:
    if isinstance(key, str):
        return isinstance(cursor, str) and key == cursor
    if _number(cursor):
        return bool(key == cursor)
    text = str(cursor).strip()
    return _NUMBER.fullmatch(text) is not None and float(text) == key


def _within(score: Any, bounds: dict[str, Any]) -> bool:
    if score is None:
        return True
    low, high = bounds.get("min"), bounds.get("max")
    return (low is None or score >= low) and (high is None or score <= high)


def _groups(ranked: list[_Hit], spec: dict[str, Any], bounds: dict[str, Any], key_field: str, offset: int,
            limit: int | None) -> list[Any]:
    """Groups in the order of their best hit, limit and offset counting groups, `size` hits each (1 by default); a record
    without the group field belongs to the group null; hits outside the bounds are dropped, and so is a group left empty."""
    group = spec["group"]
    size = 1 if group.get("size") is None else int(group["size"])
    members: dict[str, list[_Hit]] = {}
    values: dict[str, Any] = {}
    for hit in ranked:
        value = _path(hit.fields, group["field"])
        identity = _canonical(value)
        members.setdefault(identity, []).append(hit)
        values.setdefault(identity, value)
    leaders = list(members)[offset:] if limit is None else list(members)[offset:offset + limit]
    result = []
    for identity in leaders:
        kept = [_project(hit, spec, key_field) for hit in members[identity][:size] if _within(hit.score, bounds)]
        if kept:
            result.append({"group": values[identity], "hits": kept})
    return result


def _complement(x: Any) -> float:
    """1 - x in decimal arithmetic, so that 1 - 0.7 is 0.3."""
    return float(Decimal(1) - Decimal(repr(float(x))))


def _diverse(ranked: list[_Hit], mmr: dict[str, Any], offset: int, limit: int | None) -> list[_Hit]:
    """Maximal marginal relevance: from the pool, pick the hit maximizing lambda * relevance - (1 - lambda)
    * its highest similarity to a picked hit, the earlier rank breaking ties, until limit plus offset; each hit keeps its score."""
    fetch = offset + (len(ranked) if limit is None else limit)
    written = mmr.get("candidates")
    size = max(int(written), fetch) if written is not None else max(10 * fetch, 10)
    field, metric = mmr.get("vectorField"), mmr.get("metric")
    if field is None or metric is None:
        raise ValueError("mmr needs the diversity vector field and its metric")
    pool = [hit for hit in ranked if hit.vectors.get(field) is not None][:size]
    lam = float(mmr["lambda"])
    rest = _complement(lam)
    penalty = [0.0] * len(pool)
    taken = [False] * len(pool)
    picked: list[_Hit] = []
    while len(picked) < fetch:
        best, best_value = -1, 0.0
        for i, hit in enumerate(pool):
            if not taken[i]:
                value = lam * hit.score - rest * penalty[i]
                if best < 0 or value > best_value:
                    best, best_value = i, value
        if best < 0:
            break
        taken[best] = True
        chosen = pool[best]
        for i, hit in enumerate(pool):
            if not taken[i]:
                similarity = _similarity(hit.vectors[field], chosen.vectors[field], metric)
                penalty[i] = similarity if not picked else max(penalty[i], similarity)
        picked.append(chosen)
    return picked[offset:]


def _bits(value: Any) -> list[float]:
    if isinstance(value, str):
        if any(c not in "01" for c in value):
            raise ValueError("a bit vector string holds only 0 and 1")
        return [float(c) for c in value]
    if not isinstance(value, list) or not all(_number(x) for x in value):
        raise ValueError("a stored vector is a list of numbers or a bit string")
    return [float(x) for x in value]


def _similarity(a: Any, b: Any, metric: str) -> float:
    """The canonical similarity of two stored vectors under the diversity field's metric."""
    x, y = _bits(a), _bits(b)
    if len(x) != len(y):
        raise ValueError("mmr compares vectors of one dimension")
    if metric == "cosine":
        dot = norm_x = norm_y = 0.0
        for p, q in zip(x, y):
            dot += p * q
            norm_x += p * p
            norm_y += q * q
        norm = math.sqrt(norm_x * norm_y)
        return dot / norm if norm else 0.0
    total = 0.0
    if metric == "dot":
        for p, q in zip(x, y):
            total += p * q
        return total
    if metric == "euclidean":
        for p, q in zip(x, y):
            total += (p - q) * (p - q)
        return -math.sqrt(total)
    if metric == "manhattan":
        for p, q in zip(x, y):
            total += abs(p - q)
        return -total
    if metric == "hamming":
        return -float(sum(1 for p, q in zip(x, y) if (p != 0) != (q != 0)))
    if metric == "jaccard":
        both = sum(1 for p, q in zip(x, y) if p != 0 and q != 0)
        either = sum(1 for p, q in zip(x, y) if p != 0 or q != 0)
        return both / either if either else 0.0
    raise ValueError(f"unknown metric {metric}")


# ---------------------------------------------------------------- boosts


def _boost(hits: list[_Hit], boost: dict[str, Any]) -> None:
    """Each hit's score becomes its relevance with the combined boost applied; a hit no function applies to keeps it."""
    functions = boost.get("functions") or []
    combine = boost.get("combine") or "multiply"
    apply = boost.get("apply") or "multiply"
    for hit in hits:
        present = [v for v in (_function(hit.fields, f) for f in functions) if v is not None]
        if not present:
            continue
        if combine == "sum":
            value = _total(present)
        elif combine == "multiply":
            value = 1.0
            for v in present:
                value *= v
        elif combine == "max":
            value = max(present)
        elif combine == "avg":
            value = _total(present) / len(present)
        elif combine == "replace":
            value = present[0]
        else:
            raise ValueError(f"unknown boost combination {combine}")
        hit.score = _applied(apply, float(hit.score), value)


def _total(values: list[float]) -> float:
    total = 0.0
    for value in values:
        total += value
    return total


def _applied(mode: str, relevance: float, boost: float) -> float:
    if mode == "sum":
        return relevance + boost
    if mode == "multiply":
        return relevance * boost
    if mode == "max":
        return max(relevance, boost)
    if mode == "avg":
        return (relevance + boost) / 2
    if mode == "replace":
        return boost
    raise ValueError(f"unknown boost application {mode}")


def _function(fields: dict[str, Any], function: dict[str, Any]) -> float | None:
    """One boost function: the weighted field value, the weighted decay of the field's distance from the origin, or the
    weight; None where its field is null or its condition is not true."""
    when = function.get("when")
    if when is not None and _test(fields, when) is not True:
        return None
    weight = 1.0 if function.get("weight") is None else float(function["weight"])
    kind = function.get("kind")
    if kind == "condition":
        return weight
    value = _path(fields, function["field"])
    if value is None:
        return None
    if kind == "field_value":
        if not _number(value):
            raise ValueError(f"a field_value boost on a value that is not a number: {_canonical(value)}")
        return weight * value if weight != 1.0 else float(value)
    if kind != "decay":
        raise ValueError(f"unknown boost kind {kind}")
    rate = 0.5 if function.get("rate") is None else float(function["rate"])
    origin = function.get("origin")
    if isinstance(origin, str):
        distance = abs(_epoch(value) - _epoch(origin))
        scale = _seconds(function.get("scale"))
        shift = 0.0 if function.get("offset") is None else _seconds(function["offset"])
    else:
        if not _number(value):
            raise ValueError(f"a decay boost on a value that is not a number: {_canonical(value)}")
        distance = abs(float(value) - float(origin))
        scale = float(function["scale"])
        shift = 0.0 if function.get("offset") is None else float(function["offset"])
    d = max(distance - shift, 0.0) / scale
    shape_name = function.get("shape")
    if shape_name == "gauss":
        decay = math.pow(rate, math.pow(d, 2))
    elif shape_name == "exp":
        decay = math.pow(rate, d)
    elif shape_name == "linear":
        decay = max(1 - d * _complement(rate), 0.0)
    else:
        raise ValueError(f"unknown decay shape {shape_name}")
    return weight * decay if weight != 1.0 else decay


# ---------------------------------------------------------------- conditions


def _test(fields: dict[str, Any], condition: dict[str, Any]) -> bool | None:
    """A boost condition in three-valued logic, as SQL evaluates it: None where a compared value is missing."""
    if "and" in condition:
        parts = [_test(fields, c) for c in condition["and"]]
        return False if False in parts else None if None in parts else True
    if "or" in condition:
        parts = [_test(fields, c) for c in condition["or"]]
        return True if True in parts else None if None in parts else False
    if "not" in condition:
        return _test(fields, condition["not"]) is not True
    op = condition["op"]
    value = _path(fields, condition["field"])
    operand = condition.get("value")
    if op in ("is_null", "not_exists"):
        return value is None
    if op in ("is_not_null", "exists"):
        return value is not None
    if op == "neq":
        if value is None or operand is None:
            return value is not None or operand is not None
        return _canonical(value) != _canonical(operand)
    if op == "not_in":
        return _member(value, operand) is not True
    if value is None or (operand is None and op != "is_empty"):
        return None
    if op == "eq":
        return _canonical(value) == _canonical(operand)
    if op in ("gt", "gte", "lt", "lte"):
        return _ordered(op, value, operand)
    if op == "between":
        upper = condition.get("upper")
        low, high = _ordered("gte", value, operand), None if upper is None else _ordered("lte", value, upper)
        return False if False in (low, high) else None if None in (low, high) else True
    if op == "in":
        return _member(value, operand)
    if op == "contains":
        if isinstance(value, list):
            return any(_canonical(item) == _canonical(operand) for item in value)
        return operand in value if isinstance(value, str) and isinstance(operand, str) else None
    if op in ("contains_any", "contains_all"):
        if not isinstance(value, list) or not isinstance(operand, list):
            return None
        held = {_canonical(item) for item in value}
        found = [_canonical(item) in held for item in operand]
        return any(found) if op == "contains_any" else all(found)
    if op in ("like", "prefix", "contains_text"):
        if not isinstance(value, str) or not isinstance(operand, str):
            return None
        if op == "prefix":
            return value.startswith(operand)
        return operand in value if op == "contains_text" else _like(value, operand)
    if op == "is_empty":
        return len(value) == 0 if isinstance(value, (list, str)) else None
    if op.startswith("length_"):
        if not isinstance(value, (list, str)):
            return None
        return _ordered(op[7:], len(value), operand)
    raise ValueError(f"unknown condition operator {op}")


def _member(value: Any, operand: Any) -> bool | None:
    if value is None or not isinstance(operand, list):
        return None
    return any(_canonical(value) == _canonical(item) for item in operand)


def _ordered(op: str, value: Any, operand: Any) -> bool | None:
    if _rank(value) != _rank(operand) or _rank(value) == 3:
        return None
    c = _compare_values(value, operand)
    return {"eq": c == 0, "neq": c != 0, "gt": c > 0, "gte": c >= 0, "lt": c < 0, "lte": c <= 0}[op]


def _like(text: str, pattern: str) -> bool:
    """SQL LIKE: % matches any sequence, _ one character, a backslash escapes the next character."""
    tokens: list[tuple[str, str]] = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == "\\" and i + 1 < len(pattern):
            tokens.append(("char", pattern[i + 1]))
            i += 2
            continue
        tokens.append(("any", "") if c == "%" else ("one", "") if c == "_" else ("char", c))
        i += 1
    reach = [True] + [False] * len(text)
    for kind, char in tokens:
        if kind == "any":
            for j in range(1, len(text) + 1):
                reach[j] = reach[j] or reach[j - 1]
        else:
            reach = [False] + [reach[j] and (kind == "one" or text[j] == char) for j in range(len(text))]
    return reach[len(text)]


# ---------------------------------------------------------------- aggregations


def _name(aggregation: dict[str, Any]) -> str:
    return aggregation.get("name") or aggregation["kind"] + "_" + "_".join(aggregation["field"])


def _values(hits: list[_Hit], path: Sequence[str]) -> list[Any]:
    """The non-null values of a field over the hits; a list value contributes its elements."""
    values = []
    for hit in hits:
        value = _path(hit.fields, path)
        for item in value if isinstance(value, list) else [value]:
            if item is not None:
                values.append(item)
    return values


def _numbers(values: list[Any], kind: str) -> list[float]:
    for value in values:
        if not _number(value):
            raise ValueError(f"the {kind} aggregation over a value that is not a number: {_canonical(value)}")
    return [float(value) for value in values]


def _aggregate(hits: list[_Hit], aggregation: dict[str, Any]) -> Any:
    kind = aggregation["kind"]
    values = _values(hits, aggregation["field"])
    if kind == "count":
        return len(values)
    if kind in ("distinct_count", "cardinality"):
        return len({_canonical(value) for value in values})
    if kind in ("min", "max"):
        if not values:
            return None
        best = values[0]
        for value in values[1:]:
            c = _compare_values(value, best)
            if (c < 0) if kind == "min" else (c > 0):
                best = value
        return best
    if kind in ("sum", "avg", "stats"):
        numbers = _numbers(values, kind)
        total = _total(numbers) if numbers else None
        average = total / len(numbers) if numbers else None
        if kind == "sum":
            return total
        if kind == "avg":
            return average
        return {"count": len(numbers), "min": min(numbers) if numbers else None, "max": max(numbers) if numbers else None,
                "avg": average, "sum": total}
    if kind in ("terms", "facet"):
        counts: dict[str, list[Any]] = {}
        for value in values:
            counts.setdefault(_canonical(value), [value, 0])[1] += 1
        size = 10 if aggregation.get("size") is None else int(aggregation["size"])
        ordered = sorted(counts.values(), key=cmp_to_key(lambda a, b: b[1] - a[1] or _compare_values(a[0], b[0])))
        return [{"key": value, "count": count} for value, count in ordered[:size]]
    if kind == "histogram":
        interval = _interval_number(aggregation.get("interval"))
        return _buckets([math.floor(v / interval) * interval for v in _numbers(values, kind)], None)
    if kind == "date_histogram":
        interval = _seconds(aggregation.get("interval"))
        return _buckets([math.floor(_epoch(v) / interval) * interval for v in values], _timestamp)
    if kind == "percentiles":
        numbers = sorted(_numbers(values, kind))
        return {str(p): _percentile(numbers, p / 100) for p in _PERCENTS}
    raise ValueError(f"unknown aggregation kind {kind}")


def _buckets(keys: list[float], label: Any) -> list[dict[str, Any]]:
    counts: dict[float, int] = {}
    for key in keys:
        counts[key] = counts.get(key, 0) + 1
    return [{"key": key if label is None else label(key), "count": counts[key]} for key in sorted(counts)]


def _percentile(numbers: list[float], fraction: float) -> float | None:
    """percentile_cont: linear interpolation between the closest ranks."""
    if not numbers:
        return None
    position = fraction * (len(numbers) - 1)
    low = math.floor(position)
    high = min(low + 1, len(numbers) - 1)
    return numbers[low] + (numbers[high] - numbers[low]) * (position - low)


def _interval_number(interval: Any) -> float:
    if _number(interval) and interval > 0:
        return float(interval)
    if isinstance(interval, str) and _NUMBER.fullmatch(interval.strip()) and float(interval) > 0:
        return float(interval)
    raise ValueError("a histogram without a numeric interval")


# ---------------------------------------------------------------- time


def _seconds(interval: Any) -> float:
    """An interval such as 1d, 12h or 1 day 6 hours, in seconds (PostgreSQL interval units of fixed length)."""
    if _number(interval) and interval > 0:
        return float(interval)
    if not isinstance(interval, str):
        raise ValueError("an interval is a string such as 1d or 12h")
    total, position, text = 0.0, 0, interval.strip()
    while position < len(text):
        match = _INTERVAL.match(text, position)
        if match is None or match.group(2).lower() not in _UNITS:
            raise ValueError(f"an interval of numbers with the units ms, s, m, h, d or w: {interval}")
        total += float(match.group(1)) * _UNITS[match.group(2).lower()]
        position = match.end()
        while position < len(text) and text[position] == " ":
            position += 1
    if total <= 0:
        raise ValueError(f"an interval of numbers with the units ms, s, m, h, d or w: {interval}")
    return total


def _days(year: int, month: int, day: int) -> int:
    """Days since 1970-01-01 of a proleptic Gregorian date."""
    y = year - (1 if month <= 2 else 0)
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _epoch(value: Any) -> float:
    """Seconds since the epoch of an ISO 8601 timestamp (UTC unless it carries an offset), of now, or of a number of seconds."""
    if _number(value):
        return float(value)
    if value == "now":
        return time.time()
    match = _TIMESTAMP.fullmatch(value) if isinstance(value, str) else None
    if match is None:
        raise ValueError(f"a timestamp in ISO 8601 form: {_canonical(value)}")
    year, month, day = int(match.group(1)), int(match.group(2)), int(match.group(3))
    hour, minute, second = (int(match.group(i)) if match.group(i) else 0 for i in (4, 5, 6))
    if not (1 <= month <= 12 and 1 <= day <= 31 and hour < 24 and minute < 60 and second < 60):
        raise ValueError(f"a timestamp in ISO 8601 form: {value}")
    seconds = _days(year, month, day) * 86400 + hour * 3600 + minute * 60 + second + float("0" + (match.group(7) or ""))
    zone = match.group(8)
    if zone and zone not in ("Z", "z"):
        digits = zone[1:].replace(":", "")
        shift = int(digits[:2]) * 3600 + (int(digits[2:4]) * 60 if len(digits) > 2 else 0)
        seconds -= shift if zone[0] == "+" else -shift
    return seconds


def _timestamp(seconds: float) -> str:
    """A bin start as PostgreSQL prints a timestamp in JSON: 2026-11-16T12:00:00, with up to six fraction digits."""
    micros = math.floor(seconds * 1_000_000 + 0.5)
    days, rest = divmod(micros, 86_400_000_000)
    z = days + 719468
    era = z // 146097
    doe = z - era * 146097
    yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
    doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
    mp = (5 * doy + 2) // 153
    day = doy - (153 * mp + 2) // 5 + 1
    month = mp + (3 if mp < 10 else -9)
    year = yoe + era * 400 + (1 if month <= 2 else 0)
    second, fraction = divmod(rest, 1_000_000)
    text = f"{year:04d}-{month:02d}-{day:02d}T{second // 3600:02d}:{second // 60 % 60:02d}:{second % 60:02d}"
    return text + ("." + f"{fraction:06d}".rstrip("0") if fraction else "")


# ---------------------------------------------------------------- projection and values


def _project(hit: _Hit, spec: dict[str, Any], key_field: str) -> dict[str, Any]:
    """The hit object: key, score, the output fields in output order (all fields for `output *`) without the excluded ones,
    the stored vectors with with-vectors, then the highlight and the explanation as the target gave them."""
    excluded = set(spec.get("exclude") or [])
    record: dict[str, Any] = {key_field: hit.key}
    if hit.score is not None:
        record["score"] = hit.score
    output = spec.get("output")
    names = list(hit.fields) if output is None else [name for name in output if name in hit.fields]
    for name in names:
        if name != key_field and name not in excluded:
            record[name] = hit.fields[name]
    if spec.get("withVectors"):
        for name, vector in hit.vectors.items():
            if name not in excluded:
                record[name] = vector
    if hit.highlight is not None:
        record["highlight"] = hit.highlight
    if hit.explanation is not None:
        record["explanation"] = hit.explanation
    return record


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded to six digits (half to even on the exact binary
    value), integral floats as integers."""
    if isinstance(value, bool) or value is None:
        return value
    if isinstance(value, float):
        if not math.isfinite(value):
            return value
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() and abs(rounded) < 1e15 else rounded
    if isinstance(value, list):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value
